{
  "id": 35,
  "knowledge": "Fan Status Tiers",
  "description": "Illustrates the meaning of different fan account statuses on the platform.",
  "definition": "Fan status indicates their platform standing. 'Active' means regular recent activity. 'Inactive' means no recent activity. 'VIP' is a special high-value status granted based on contribution and spending."
}

{
  "id": 19,
  "knowledge": "Whale Fan",
  "description": "A fan who demonstrates extremely high in-session spending, representing a top-tier financial contributor.",
  "definition": "A fan is classified as a Whale Fan if their Fan Monetization Index (FMI) is greater than 20."
}

{
  "id": 0,
  "knowledge": "Fan Monetization Index (FMI)",
  "description": "Measures a fan's direct financial contribution per minute of engagement, indicating their propensity for in-session spending.",
  "definition": "FMI = \\frac{\\text{Total Gift Value in USD}}{\\text{Session Duration in Minutes}}"
}

{
  "id": 18,
  "knowledge": "Premium Member",
  "description": "Identifies fans who have a paid membership subscription.",
  "definition": "A fan is considered a Premium Member if their membership type is not 'Free'. This includes tiers like 'Basic', 'Elite', etc."
}

{
  "id": 21,
  "knowledge": "High-Value Member",
  "description": "A fan with a paid subscription who consistently contributes significant financial value to the platform on a monthly basis.",
  "definition": "A fan is a High-Value Member if they are a Premium Member and their Fan Financial Value (FFV) is greater than $50 per month."
}

{
  "id": 3,
  "knowledge": "Fan Financial Value (FFV)",
  "description": "Estimates a fan's monthly financial contribution to the platform, serving as a proxy for their lifetime value.",
  "definition": "FFV = \\frac{\\text{Total Spending in USD}}{\\text{Membership Duration in Days} / 30.44}"
}

{
  "id": 50,
  "knowledge": "Fan Segments",
  "description": "Defines four distinct fan categories by segmenting the user base into a 2x2 grid based on their relative financial value and support load.",
  "definition": "A classification of fans based on their rank for Fan Financial Value (FFV) and Support Load Score (SLS). Fans are split into top/bottom 50% for each metric to create four quadrants: 'Ideal Fans', 'At-Risk VIPs', 'Quiet Majority', and 'Resource Drain'."
}

{
  "id": 32,
  "knowledge": "Idol Superfan",
  "description": "An elite fan who combines high spending with high event participation, representing the most dedicated segment of the user base.",
  "definition": "A fan is an Idol Superfan if they are classified as both a Whale Fan and an Event Enthusiast."
}

{
  "id": 34,
  "knowledge": "Power User",
  "description": "A highly engaged premium member who uses the platform extensively across multiple devices.",
  "definition": "A fan is a Power User if they are a Premium Member, have a total session count greater than 400, and use more than 2 devices."
}

{
  "id": 30,
  "knowledge": "Event Enthusiast",
  "description": "A fan who actively and frequently participates in a wide range of platform events, especially high-value ones like meet-and-greets.",
  "definition": "A fan is an Event Enthusiast if their Event Participation Score (EPS) is greater than 25."
}

{
  "id": 25,
  "knowledge": "At-Risk Fan",
  "description": "A fan who shows signs of disengagement or has been flagged as having a high probability of churning.",
  "definition": "A fan is considered At-Risk if their Platform Stickiness Score (PSS) is below 0.4 or their churn flag is 'High'."
}

{
  "id": 41,
  "knowledge": "Churn Risk Flag",
  "description": "Defines the predictive flags for a fan's likelihood of leaving the platform.",
  "definition": "A predictive classification of a fan's likelihood to stop using the platform. 'High' indicates a strong probability of churning soon. 'Medium' indicates a moderate risk. 'Low' indicates a loyal and stable user."
}

{
  "id": 42,
  "knowledge": "Spending Frequency",
  "description": "Illustrates the different patterns of fan spending behavior.",
  "definition": "Describes a fan's purchasing behavior pattern. 'Weekly' or 'Daily' indicates consistent spending. 'Occasional' indicates sporadic purchasing."
}

{
  "id": 26,
  "knowledge": "Loyal Achiever",
  "description": "A fan who is deeply engaged with the platform's gamification systems, rapidly earning achievements and progressing through loyalty tiers.",
  "definition": "A fan is a Loyal Achiever if their Achievement Density (AD) is greater than 0.2 and their Loyalty Progression Rate (LPR) is greater than 500."
}

{
  "id": 22,
  "knowledge": "Collector Fan",
  "description": "A fan who is highly focused on acquiring platform collectibles, both digital and physical.",
  "definition": "A fan is a Collector Fan if their Collection Rate (CR) is greater than 50 and their collection completion rate is above 75%."
}

{
  "id": 28,
  "knowledge": "Platform Promoter",
  "description": "A fan who is highly likely to recommend the platform to others, as indicated by a top-tier NPS score.",
  "definition": "A fan is a Platform Promoter if they are classified in the 'Promoters' category based on NPS Score Tiers."
}

{
  "id": 23,
  "knowledge": "Community Influencer",
  "description": "A fan with significant social capital, characterized by a large and engaged follower base.",
  "definition": "A fan is a Community Influencer if their Follower-to-Following Ratio (FFR) is greater than 2.0 and their Community Influence Index (CII) is greater than 10000."
}

{
  "id": 29,
  "knowledge": "Social Butterfly",
  "description": "A fan who is exceptionally well-connected and active within the platform's social communities.",
  "definition": "A fan is a Social Butterfly if their Social Capital Score (SCS) is greater than 1000 and they are a member of more than 5 community groups."
}

{
  "id": 20,
  "knowledge": "Engaged Lurker",
  "description": "A fan who actively consumes a large amount of content but participates minimally in social chat.",
  "definition": "A fan is an Engaged Lurker if their Content Consumption Index (CCI) is greater than 0.5 and their Chattiness Score (CS) is less than 0.5."
}

{
  "id": 31,
  "knowledge": "Professional Fan",
  "description": "An adult fan who identifies with a professional occupation, representing a key demographic segment.",
  "definition": "A fan is a Professional Fan if they are in the 'Adult' or 'Senior' Fan Age Category and their occupation path is 'Professional'."
}

{
  "id": 33,
  "knowledge": "Rising Star Influencer",
  "description": "A fan with a demonstrated ability to create viral content who is on the cusp of becoming a major community influencer.",
  "definition": "A fan is a Rising Star Influencer if their Viral Potential Score (VPS) is greater than 50 and their Community Influence Index (CII) is between 1000 and 10000."
}

{
  "id": 24,
  "knowledge": "Super Creator",
  "description": "A fan who is a prolific and high-quality content creator, contributing significantly to the platform's user-generated content.",
  "definition": "A fan is a Super Creator if their Content Creator Score (CCS) is greater than 200."
}

{
  "id": 58,
  "knowledge": "Lone Wolf",
  "description": "A fan who is highly engaged with platform goals (achievements) but has low social connectivity.",
  "definition": "A fan is a 'Lone Wolf' if their Achievement Density (AD) is greater than 0.5 AND their Social Capital Score (SCS) is less than 100."
}

{
  "id": 27,
  "knowledge": "High-Maintenance Fan",
  "description": "A fan who frequently requires customer support, indicating potential issues with their user experience or platform stability.",
  "definition": "A fan is classified as High-Maintenance if their Support Load Score (SLS) is greater than 10."
}

{
  "id": 56,
  "knowledge": "Peak Monetization Index",
  "description": "The highest Fan Monetization Index (FMI) a fan has achieved in any single interaction session.",
  "definition": "The maximum value of the Fan Monetization Index (FMI) calculated across all of a fan's interaction sessions."
}

{
  "id": 11,
  "knowledge": "Event Participation Score (EPS)",
  "description": "A weighted score that measures a fan's engagement with platform events, prioritizing in-person attendance.",
  "definition": "EPS = (\\text{Online Events} \\times 1) + (\\text{Offline Events} \\times 1.5) + (\\text{Meet-and-Greets} \\times 2)"
}

{
  "id": 12,
  "knowledge": "Platform Stickiness Score (PSS)",
  "description": "Measures a fan's loyalty and connection to the platform based on their interaction consistency and session stability.",
  "definition": "PSS = \\frac{\\text{Interaction Consistency Score} + \\text{Platform Stability Score}}{2}"
}

{
  "id": 8,
  "knowledge": "Achievement Density (AD)",
  "description": "Measures the rate at which a fan earns achievements, indicating their level of engagement with platform goals.",
  "definition": "AD = \\frac{\\text{Total Achievements Unlocked}}{\\text{Membership Duration in Days}}"
}

{
  "id": 13,
  "knowledge": "Loyalty Progression Rate (LPR)",
  "description": "Measures the efficiency of a fan's progression through loyalty tiers based on points accumulated.",
  "definition": "LPR = \\frac{\\text{Total Loyalty Points}}{\\text{Current Tier Level}}"
}

{
  "id": 15,
  "knowledge": "Collection Rate (CR)",
  "description": "Measures the total number of digital and physical collectible items a fan owns.",
  "definition": "CR = \\text{Digital Items Owned} + \\text{Physical Items Owned}"
}

{
  "id": 14,
  "knowledge": "Social Capital Score (SCS)",
  "description": "Represents the size and strength of a fan's social network on the platform.",
  "definition": "SCS = \\text{Social Network Size} + (\\text{Friend Connections} \\times 1.5)"
}

{
  "id": 7,
  "knowledge": "Community Influence Index (CII)",
  "description": "A composite score that measures a fan's overall influence within the community, based on their social network reach and recognized influence.",
  "definition": "CII = \\sqrt{\\text{Follower Count} \\times \\text{Content Reach}}"
}

{
  "id": 10,
  "knowledge": "Viral Potential Score (VPS)",
  "description": "Assesses a fan's ability to create and participate in viral trends.",
  "definition": "VPS = \\text{Viral Content Pieces} \\times (1 + \\text{Trend Participation Count})"
}

{
  "id": 6,
  "knowledge": "Content Creator Score (CCS)",
  "description": "Evaluates a fan's contribution as a content creator by combining the volume and quality of their user-generated content.",
  "definition": "CCS = (\u03a3 \\text{Content Submissions} + \\text{Collaborations}) \\times \\text{Average Content Quality Rating}"
}

{
  "id": 1,
  "knowledge": "Content Consumption Index (CCI)",
  "description": "Quantifies a fan's level of passive engagement by measuring the hours of content they watch relative to their session time.",
  "definition": "CCI = \\frac{\\text{Total Watch Hours}}{\\text{Session Duration in Minutes}}"
}

{
  "id": 2,
  "knowledge": "Chattiness Score (CS)",
  "description": "Measures a fan's active communication during a session, reflecting their level of social interaction.",
  "definition": "CS = \\frac{\\text{Number of Chat Messages Sent}}{\\text{Session Duration in Minutes}}"
}

{
  "id": 9,
  "knowledge": "Support Load Score (SLS)",
  "description": "Quantifies the amount of support resources a fan utilizes, based on their submission of tickets and issue reports.",
  "definition": "SLS = \\text{Support Tickets} + \\text{Bug Reports} + \\text{Technical Issue Reports}"
}

{
  "id": 17,
  "knowledge": "NPS Score Tiers",
  "description": "Classifies fans into categories based on their Net Promoter Score, indicating their likelihood to recommend the platform.",
  "definition": "Net Promoter Score (NPS) is categorized as: Promoters (score 9-10), Passives (score 7-8), and Detractors (score 0-6)."
}

{
  "id": 16,
  "knowledge": "Fan Age Category",
  "description": "Categorizes fans into distinct age groups for demographic analysis.",
  "definition": "Fan age is categorized as: Teen (<=18), Young Adult (19-29), Adult (30-49), Senior (>=50)."
}

{
  "id": 4,
  "knowledge": "Merchandise Affinity Score (MAS)",
  "description": "Calculates the proportion of a fan's total spending that is dedicated to merchandise, indicating their interest in physical goods.",
  "definition": "MAS = \\frac{\\text{Total Merchandise Spend in USD}}{\\text{Total Spending in USD}}"
}

{
  "id": 5,
  "knowledge": "Follower-to-Following Ratio (FFR)",
  "description": "Measures a fan's social influence by comparing the number of users who follow them to the number of users they follow.",
  "definition": "FFR = \\frac{\\text{Follower Count}}{\\text{Following Count}}, \\text{ where Following Count is > 0}"
}

{
  "id": 40,
  "knowledge": "Idol Type Classification",
  "description": "Explains the different types of virtual idols on the platform.",
  "definition": "Describes the nature of the virtual idol. '2D' refers to traditionally animated characters. '3D' refers to computer-generated models. 'AI Generated' refers to idols created and/or operated by artificial intelligence."
}

{
  "id": 38,
  "knowledge": "Reputation Level",
  "description": "Describes the hierarchy of fan reputation and trustworthiness within the community.",
  "definition": "Represents a fan's standing and trustworthiness in the community. Common levels are 'Respected', 'Established', and 'Elite'."
}

{
  "id": 45,
  "knowledge": "Moderation Status",
  "description": "Defines the account standings related to compliance with platform rules.",
  "definition": "Reflects a fan's account standing. 'Good Standing' means no issues. 'Warning' indicates a minor violation. 'Restricted' indicates temporary limitations due to a serious violation."
}

{
  "id": 46,
  "knowledge": "Privacy Setting Levels",
  "description": "Explains the different profile privacy options available to fans.",
  "definition": "Indicates the level of information a fan chooses to share. 'Public' allows anyone to see their profile. 'Private' restricts profile visibility to approved connections."
}

